sections.body:
在空的练习目录安装 npm install --save-exact source-map@0.7.6，保存下面为 stack-map.mjs，再运行 node stack-map.mjs。保留依赖锁文件。本例手工定义两个映射点，不是 Cocos 或压缩器产出的真实映射，也不执行示例 throw。

[source-map 0.7.6 文档](https://raw.githubusercontent.com/mozilla/source-map/0.7.6/README.md) 规定 API 行号从 1、列号从 0 开始；采集器必须先统一坐标约定，不能对所有平台的栈文本盲目减一。with 会在回调结束后释放 consumer。

```js
/**
 * @file 用两份人工映射演示版本错配；不运行游戏或压缩器。
 * @author liliwei
 * @date 2026-11-05
 * @LastEditors liliwei
 * @LastEditTime 2026-11-05
 */
import { createHash } from 'node:crypto';
import { SourceMapGenerator, SourceMapConsumer } from 'source-map';

/** @param {string} text UTF-8 内容。@returns {string} 内容摘要。 */
export function hash(text) {
  return createHash('sha256').update(text).digest('hex');
}

/** @param {string} build 构建 ID。@param {string} source 原文件。
 * @param {number} line 原行号。@returns {object} 人工构建档案。 */
export function fixture(build, source, line) {
  const code = `throw new Error("${build}");`;
  const generator = new SourceMapGenerator({ file: 'game.js' });
  generator.addMapping({ generated: { line: 1, column: 10 },
    original: { line, column: 2 }, source });
  const map = generator.toString();
  return { code, map, manifest: { build, file: 'game.js',
    codeSha: hash(code), mapSha: hash(map) } };
}

/** @param {object} event 已规范为行从 1、列从 0 的栈帧。
 * @param {object} artifact 来自可信构建档案。
 * @returns {Promise<object>} 位置候选或明确的未解析原因。 */
export async function locate(event, artifact) {
  if (!Number.isSafeInteger(event.line) || event.line < 1 ||
      !Number.isSafeInteger(event.column) || event.column < 0) {
    throw new TypeError('invalid position');
  }
  const m = artifact.manifest;
  if (event.build !== m.build || event.file !== m.file ||
      event.codeSha !== m.codeSha) return { status: 'wrong-build' };
  if (hash(artifact.code) !== m.codeSha || hash(artifact.map) !== m.mapSha) {
    return { status: 'bad-artifact' };
  }
  return SourceMapConsumer.with(artifact.map, null, consumer => {
    const pos = consumer.originalPositionFor({
      line: event.line, column: event.column });
    return pos.source === null ? { status: 'unmapped' }
      : { status: 'mapped', ...pos };
  });
}

export const a = fixture('a', 'src/BagView.ts', 42);
export const b = fixture('b', 'src/ShopView.ts', 9);
export const event = { build: 'a', file: 'game.js',
  codeSha: a.manifest.codeSha, line: 1, column: 10 };

console.log('wrong map, no guard', await SourceMapConsumer.with(
  b.map, null, c => c.originalPositionFor({ line: 1, column: 10 })));
console.log('right archive', await locate(event, a));
console.log('wrong archive', await locate(event, b));
console.log('swapped map', await locate(event, { ...a, map: b.map }));
```

正文原样在 Node.js 22.16.0 实跑，结果如下；表内列号均从 0 起算。

| 输入方式 | 实际结果 |
| --- | --- |
| a 的坐标直接交给 b.map | src/ShopView.ts，第 9 行、第 2 列；库没有报版本错 |
| a 的事件与 a 的档案 | mapped，src/BagView.ts，第 42 行、第 2 列 |
| a 的事件与 b 的档案 | wrong-build |
| a 的档案中只换入 b.map | bad-artifact |

另查了 6 项非法坐标、未知构建、错误文件、错误摘要和脚本字节改变，均按合同拒绝；输入没有被修改。第 1 行第 9 列与第 2 行返回 unmapped；第 1 行第 11 列仍返回前一个映射点。库默认采用前方最近的映射，不能把“有位置”解释为逐字符精确定位。

还有一个刻意保留的失败：归档时就把 b.map 配给 a，并重新填写一致的摘要，检查仍会放行。哈希只能检查相对于清单的一致性，不能证明清单的来源正确。事件身份也须由发布与采集链路正确提供。因此上线前要用已知位置的测试异常验整条链路；格式通过与真实归因是两层证据。这里的短函数假定档案结构可信，解析异常由调用方记录为未解析，不能充当通用日志导入器。
